(() => {
  const apply = () => {
    const card = document.querySelector('[data-name="maehihw cafetera portatil capsulas multicapsulas cafe molido viajes oficina camping"]');
    if (!card) return;
    const link = card.querySelector('.offer-button');
    if (link) link.href = 'https://amzn.to/4da0DT2';
    const art = card.querySelector('.product-art');
    if (!art) return;
    art.style.cssText = 'display:flex;align-items:center;justify-content:center;padding:0;background:#fff;overflow:hidden;';
    art.innerHTML = '<img alt="Maehihw Cafetera Portátil Multicápsulas" loading="lazy" style="width:auto;height:auto;max-width:82%;max-height:82%;object-fit:contain;display:block;margin:auto" src="data:image/jpeg;base64,">';
    art.removeAttribute('aria-hidden');
    art.setAttribute('role','img');
    art.setAttribute('aria-label','Maehihw Cafetera Portátil Multicápsulas');
  };
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', apply, { once: true });
  else apply();
})();